local M = class("FulwinArenaInvitePopControl", LikeOO.OOControlBase)

function M:onEnter()

end

function M:onHandle(msg, data)
    if msg == 99999 then -- 关闭
        self:closeView()
    elseif msg == "btn_titleInfoBtn" then
        -- 模拟赛旁的感叹号按钮
        self:openView("Pops.CommonHelpPop", { title = "fylt_str_0012", content = "Fengyun_challenge_tips" })
    elseif msg == "btn_closePlayer" then
        -- 换人
        self.m_model.m_rivalData = nil    
        self.m_view:refreshUI()
    elseif msg == "btn_playerInfo" then
        local item_data = self.m_model.m_rivalData
        local open_tab_index = self.m_model.m_selectPeopleCount == 1 and 2 or 1
        self:openView("Pops.PlayerInfo", {uid = item_data.user.uid, look_model = 9, open_tab_index = open_tab_index, team_type = self.m_model.m_selectPeopleCount, fair = self.m_model.m_isJustice and 1 or 0})
    elseif msg == "btn_one" then
        -- 一人
        self:setTeamPeopleCount(1)
        audio:SendEvtUI("Play_UI_NormalClick")
    elseif msg == "btn_three" then
        -- 三人
        self:setTeamPeopleCount(3)
        audio:SendEvtUI("Play_UI_NormalClick")
    elseif msg == "btn_justice" then
        -- 公平模式
        self.m_model:modifyJusticeData(not self.m_model.m_isJustice)
        self.m_view:refreshUI()
        audio:SendEvtUI("Play_UI_NormalClick")
    elseif msg == "btn_battle" then
        -- 开战
        if self.m_model.m_rivalData == nil then
            GameUtil:lookInfoTips(self.m_control, {msg = Language:getTextByKey("fylt_str_0038"), delay_close = 2})
            return
        end
        local justiceIndex = self.m_model.m_isJustice and 1 or 0
        local function netCallback(response)
            -- 1 公平，0 不公平
            if self.m_model.m_selectPeopleCount == 1 then
                self:openView("Formation",{mode = GlobalConfig.BATTLE_MODE.FULWIN_AREA_ATTACK_ONE, def_data = response, defend_uid = response.user.uid, formation_index = 1, fair_fulwin = justiceIndex})
            else
                self:openView("Formation",{mode = GlobalConfig.BATTLE_MODE.FULWIN_AREA_ATTACK_THREE, def_data = response, defend_uid = response.user.uid, formation_index = 1, fair_fulwin = justiceIndex})
            end
        end
        local params = {defend_uid = self.m_model.m_rivalData.user.uid, team_type = self.m_model.m_selectPeopleCount, fair = justiceIndex}
        self.m_model:getNetData("friend_arena_select_defend_teams", params, netCallback)
    elseif msg == "btn_addPlayerBtn" then
        -- 选人
        self:openView("FulwinArena.FulwinArenaInviteListPop", {team_type = self.m_model.m_selectPeopleCount, fair = self.m_model.m_isJustice})
    elseif msg == "item_battle" then
        -- 上人了
        self.m_model.m_rivalData = data.playerData
        self.m_view:refreshUI()
    end
end

function M:setTeamPeopleCount(count)
    if self.m_model.m_selectPeopleCount == count then
        return
    end
    self.m_model:setSelectPeopleCount(count)
    self.m_view:refreshUI()
end

function M:activityOverExamine(response)
    if response["end"] == 1 then
        GameUtil:lookInfoTips(self, {msg = Language:getTextByKey("gf_str_0085"), delay_close = 2})
        self:closeView()
        return true
    end
    return false
end

return M